import type { ColorPickerInputField as ColorPickerInputFieldModelType } from './color.js';

import Root from './color-picker.svelte';
import Trigger from './color-picker-trigger.svelte';
import Content from './color-picker-content.svelte';
import Area from './color-picker-area.svelte';
import HueSlider from './color-picker-hue-slider.svelte';
import AlphaSlider from './color-picker-alpha-slider.svelte';
import Swatch from './color-picker-swatch.svelte';
import EyeDropper from './color-picker-eye-dropper.svelte';
import FormatSelect from './color-picker-format-select.svelte';
import Input from './color-picker-input.svelte';
import InputField from './color-picker-input-field.svelte';

export type {
	ColorPickerChildProps,
	ColorPickerProps,
	ColorPickerRootProps
} from './color-picker.svelte';
export type {
	ColorPickerTriggerChildProps,
	ColorPickerTriggerProps
} from './color-picker-trigger.svelte';
export type { ColorPickerContentProps } from './color-picker-content.svelte';
export type { ColorPickerAreaChildProps, ColorPickerAreaProps } from './color-picker-area.svelte';
export type { ColorPickerHueSliderProps } from './color-picker-hue-slider.svelte';
export type { ColorPickerAlphaSliderProps } from './color-picker-alpha-slider.svelte';
export type {
	ColorPickerSwatchChildProps,
	ColorPickerSwatchProps
} from './color-picker-swatch.svelte';
export type {
	ColorPickerEyeDropperChildProps,
	ColorPickerEyeDropperProps
} from './color-picker-eye-dropper.svelte';
export type {
	ColorPickerFormatSelectChildProps,
	ColorPickerFormatSelectProps
} from './color-picker-format-select.svelte';
export type { ColorPickerInputProps } from './color-picker-input.svelte';
export {
	colorPickerInputVariants,
	type ColorPickerInputFieldPosition,
	type ColorPickerInputFieldProps
} from './color-picker-input-field.svelte';

export {
	ColorPickerAreaState,
	ColorPickerRootState,
	getColorPickerContext,
	setColorPickerContext,
	type ColorPickerAreaStateProps,
	type ColorPickerRootStateProps,
	type EyeDropperApi
} from './color-picker.svelte.js';

export {
	clampChannel,
	COLOR_FORMATS,
	colorToString,
	describeColor,
	getInputFields,
	hexToRgb,
	hslToRgb,
	hsvToRgb,
	isColorFormat,
	parseColorString,
	rgbToHex,
	rgbToHsl,
	rgbToHsv,
	type ColorFormat,
	type ColorPickerInputChannel,
	type ColorPickerInputFieldsInput,
	type HslColor,
	type HsvaColor,
	type RgbaColor
} from './color.js';

/**
 * The channel model {@link getInputFields} returns, one entry per rendered field.
 *
 * `contracts/color-picker-api.md` asks for this to be re-exported as `ColorPickerInputField`, but
 * that name is already the `InputField` part's `ColorPicker*` alias below and a module cannot export
 * one name as both a type and a value. The component alias wins — it is the documented public part —
 * so the model carries the `Model` suffix here. It is still `ColorPickerInputField` when imported
 * straight from `./color.js`.
 */
export type ColorPickerInputFieldModel = ColorPickerInputFieldModelType;

export {
	Root,
	Trigger,
	Content,
	Area,
	HueSlider,
	AlphaSlider,
	Swatch,
	EyeDropper,
	FormatSelect,
	Input,
	InputField,
	//
	Root as ColorPicker,
	Trigger as ColorPickerTrigger,
	Content as ColorPickerContent,
	Area as ColorPickerArea,
	HueSlider as ColorPickerHueSlider,
	AlphaSlider as ColorPickerAlphaSlider,
	Swatch as ColorPickerSwatch,
	EyeDropper as ColorPickerEyeDropper,
	FormatSelect as ColorPickerFormatSelect,
	Input as ColorPickerInput,
	InputField as ColorPickerInputField
};

/**
 * Pure colour maths for `<ColorPicker>` — no DOM, no runes, no globals.
 *
 * Ported from the numeric helpers upstream inlines in
 * `.reference/diceui/docs/registry/bases/radix/ui/color-picker.tsx:85-410`. `color-swatch`'s own
 * `color.ts` owns only the background/checkerboard helpers, so the conversions live here (research
 * R-13); the swatch's checkerboard is composed rather than duplicated.
 */

/** Every display format, in upstream declaration order. */
export const COLOR_FORMATS = ['hex', 'rgb', 'hsl', 'hsb'] as const;

/** The notation the colour is displayed and edited in. Never affects the stored colour. */
export type ColorFormat = (typeof COLOR_FORMATS)[number];

/** The authoritative colour: 8-bit RGB channels plus a `0..1` alpha. */
export type RgbaColor = { r: number; g: number; b: number; a: number };

/** The authoritative hue/saturation/brightness view: degrees, percent, percent, `0..1` alpha. */
export type HsvaColor = { h: number; s: number; v: number; a: number };

/** Derived on demand for the `hsl` fields and for {@link colorToString}; never stored. */
export type HslColor = { h: number; s: number; l: number };

/** One editable channel of the active format. `hex` edits the whole colour at once. */
export type ColorPickerInputChannel = 'hex' | 'r' | 'g' | 'b' | 'h' | 's' | 'l' | 'v' | 'a';

/** One rendered field of `<ColorPicker.Input>`, and the model `<ColorPicker.InputField>` reads. */
export type ColorPickerInputField = {
	/** Which channel this field commits to. */
	channel: ColorPickerInputChannel;
	/** The exact upstream `aria-label`. */
	label: string;
	/** The canonical display value the field falls back to whenever it is not being edited. */
	value: string;
	/** The placeholder shown when the field is empty. */
	placeholder: string;
	/** Whether the field takes a number, which adds `inputmode`/`pattern`/`min`/`max`. */
	numeric: boolean;
	/** The inclusive lower bound of a numeric field. */
	min?: number;
	/** The inclusive upper bound of a numeric field. */
	max?: number;
	/** Where the field sits in the joined row, driving its border-radius variant. */
	position: 'first' | 'middle' | 'last' | 'isolated';
};

/** The input {@link getInputFields} derives its field set from. */
export type ColorPickerInputFieldsInput = {
	format: ColorFormat;
	rgb: RgbaColor;
	hsv: HsvaColor;
	withoutAlpha: boolean;
};

const HEX_SHORTHAND_PATTERN = /^#?([a-f\d])([a-f\d])([a-f\d])$/i;
const HEX_PATTERN = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i;
const HEX_STRING_PATTERN = /^#([a-fA-F0-9]{3}|[a-fA-F0-9]{6})$/;
const RGB_PATTERN = /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+))?\s*\)$/;
const HSL_PATTERN = /^hsla?\(\s*(\d+)\s*,\s*(\d+)%\s*,\s*(\d+)%\s*(?:,\s*([\d.]+))?\s*\)$/;
const HSB_PATTERN = /^hsba?\(\s*(\d+)\s*,\s*(\d+)%\s*,\s*(\d+)%\s*(?:,\s*([\d.]+))?\s*\)$/;

/**
 * Whether an untyped runtime value is one of {@link COLOR_FORMATS} — the `<Select>` hands its value
 * back as a bare `string`, and anything unrecognised falls back to `"hex"` at the call site.
 */
export function isColorFormat(value: unknown): value is ColorFormat {
	return typeof value === 'string' && (COLOR_FORMATS as readonly string[]).includes(value);
}

/**
 * Clamp a computed channel into `[min, max]` and round it to a whole unit. Used for values the
 * component computes itself (pointer geometry, arrow steps); values arriving from an input field are
 * *rejected* rather than clamped, matching upstream.
 *
 * A non-finite input collapses to `min`.
 */
export function clampChannel(value: number, min: number, max: number): number {
	if (!Number.isFinite(value)) return min;
	return Math.round(Math.min(max, Math.max(min, value)));
}

/**
 * Parse a three- or six-digit hex string, with or without the leading `#`.
 *
 * Anything else yields black, keeping `alpha` — upstream's fallback. Unlike upstream, three-digit
 * shorthand expands rather than collapsing to black (spec Assumptions, "3-digit hex").
 */
export function hexToRgb(hex: string, alpha?: number): RgbaColor {
	const a = alpha ?? 1;

	const shorthand = HEX_SHORTHAND_PATTERN.exec(hex);
	if (shorthand) {
		const expand = (digit: string) => Number.parseInt(`${digit}${digit}`, 16);
		return {
			r: expand(shorthand[1] ?? '0'),
			g: expand(shorthand[2] ?? '0'),
			b: expand(shorthand[3] ?? '0'),
			a
		};
	}

	const result = HEX_PATTERN.exec(hex);
	return result
		? {
				r: Number.parseInt(result[1] ?? '0', 16),
				g: Number.parseInt(result[2] ?? '0', 16),
				b: Number.parseInt(result[3] ?? '0', 16),
				a
			}
		: { r: 0, g: 0, b: 0, a };
}

/** Render a colour as a lowercase, zero-padded `#rrggbb`. The alpha is dropped. */
export function rgbToHex(color: RgbaColor): string {
	const toHex = (n: number) => {
		const hex = Math.round(n).toString(16);
		return hex.length === 1 ? `0${hex}` : hex;
	};
	return `#${toHex(color.r)}${toHex(color.g)}${toHex(color.b)}`;
}

/**
 * RGBA → HSVA, with `s`/`v` rounded to whole percents. Lossy in that rounding, which is exactly why
 * both representations are stored side by side rather than derived from one another (research R-02).
 */
export function rgbToHsv(color: RgbaColor): HsvaColor {
	const r = color.r / 255;
	const g = color.g / 255;
	const b = color.b / 255;

	const max = Math.max(r, g, b);
	const min = Math.min(r, g, b);
	const diff = max - min;

	let h = 0;
	if (diff !== 0) {
		switch (max) {
			case r:
				h = ((g - b) / diff) % 6;
				break;
			case g:
				h = (b - r) / diff + 2;
				break;
			case b:
				h = (r - g) / diff + 4;
				break;
		}
	}
	h = Math.round(h * 60);
	if (h < 0) h += 360;

	const s = max === 0 ? 0 : diff / max;
	const v = max;

	return { h, s: Math.round(s * 100), v: Math.round(v * 100), a: color.a };
}

/** HSVA → RGBA, rounded to whole 8-bit channels. The alpha is carried straight through. */
export function hsvToRgb(hsv: HsvaColor): RgbaColor {
	const h = hsv.h / 360;
	const s = hsv.s / 100;
	const v = hsv.v / 100;

	const i = Math.floor(h * 6);
	const f = h * 6 - i;
	const p = v * (1 - s);
	const q = v * (1 - f * s);
	const t = v * (1 - (1 - f) * s);

	let r: number;
	let g: number;
	let b: number;

	switch (i % 6) {
		case 0:
			r = v;
			g = t;
			b = p;
			break;
		case 1:
			r = q;
			g = v;
			b = p;
			break;
		case 2:
			r = p;
			g = v;
			b = t;
			break;
		case 3:
			r = p;
			g = q;
			b = v;
			break;
		case 4:
			r = t;
			g = p;
			b = v;
			break;
		case 5:
			r = v;
			g = p;
			b = q;
			break;
		default:
			r = 0;
			g = 0;
			b = 0;
	}

	return { r: Math.round(r * 255), g: Math.round(g * 255), b: Math.round(b * 255), a: hsv.a };
}

/** RGBA → HSL, every component rounded to a whole unit. The alpha is not part of the result. */
export function rgbToHsl(color: RgbaColor): HslColor {
	const r = color.r / 255;
	const g = color.g / 255;
	const b = color.b / 255;

	const max = Math.max(r, g, b);
	const min = Math.min(r, g, b);
	const diff = max - min;
	const sum = max + min;

	const l = sum / 2;

	let h = 0;
	let s = 0;

	if (diff !== 0) {
		s = l > 0.5 ? diff / (2 - sum) : diff / sum;

		if (max === r) {
			h = (g - b) / diff + (g < b ? 6 : 0);
		} else if (max === g) {
			h = (b - r) / diff + 2;
		} else if (max === b) {
			h = (r - g) / diff + 4;
		}
		h /= 6;
	}

	return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) };
}

/** HSL → RGBA, rounded to whole 8-bit channels, with the supplied alpha attached. */
export function hslToRgb(hsl: HslColor, alpha = 1): RgbaColor {
	const h = hsl.h / 360;
	const s = hsl.s / 100;
	const l = hsl.l / 100;

	const c = (1 - Math.abs(2 * l - 1)) * s;
	const x = c * (1 - Math.abs(((h * 6) % 2) - 1));
	const m = l - c / 2;

	let r = 0;
	let g = 0;
	let b = 0;

	if (h >= 0 && h < 1 / 6) {
		r = c;
		g = x;
	} else if (h >= 1 / 6 && h < 2 / 6) {
		r = x;
		g = c;
	} else if (h >= 2 / 6 && h < 3 / 6) {
		g = c;
		b = x;
	} else if (h >= 3 / 6 && h < 4 / 6) {
		g = x;
		b = c;
	} else if (h >= 4 / 6 && h < 5 / 6) {
		r = x;
		b = c;
	} else if (h >= 5 / 6 && h < 1) {
		r = c;
		b = x;
	}

	return {
		r: Math.round((r + m) * 255),
		g: Math.round((g + m) * 255),
		b: Math.round((b + m) * 255),
		a: alpha
	};
}

/**
 * Render a colour in the given notation. The `a` suffix (`rgba`/`hsla`/`hsba`) appears only below
 * full opacity; `hex` never carries alpha, which is what the hidden form input submits.
 */
export function colorToString(color: RgbaColor, format: ColorFormat = 'hex'): string {
	switch (format) {
		case 'rgb':
			return color.a < 1
				? `rgba(${color.r}, ${color.g}, ${color.b}, ${color.a})`
				: `rgb(${color.r}, ${color.g}, ${color.b})`;
		case 'hsl': {
			const hsl = rgbToHsl(color);
			return color.a < 1
				? `hsla(${hsl.h}, ${hsl.s}%, ${hsl.l}%, ${color.a})`
				: `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`;
		}
		case 'hsb': {
			const hsv = rgbToHsv(color);
			return color.a < 1
				? `hsba(${hsv.h}, ${hsv.s}%, ${hsv.v}%, ${color.a})`
				: `hsb(${hsv.h}, ${hsv.s}%, ${hsv.v}%)`;
		}
		default:
			return rgbToHex(color);
	}
}

/**
 * Read any of the four notations back into a colour, or `null` when the string is not one of them.
 *
 * This is what an incoming controlled `value` is parsed with, so a consumer wiring `value` and
 * `onValueChange` together keeps working in every format (research R-03).
 */
export function parseColorString(value: string): RgbaColor | null {
	const trimmed = value.trim();

	if (trimmed.startsWith('#')) {
		return HEX_STRING_PATTERN.test(trimmed) ? hexToRgb(trimmed) : null;
	}

	const rgbMatch = RGB_PATTERN.exec(trimmed);
	if (rgbMatch) {
		return {
			r: Number.parseInt(rgbMatch[1] ?? '0', 10),
			g: Number.parseInt(rgbMatch[2] ?? '0', 10),
			b: Number.parseInt(rgbMatch[3] ?? '0', 10),
			a: rgbMatch[4] ? Number.parseFloat(rgbMatch[4]) : 1
		};
	}

	const hslMatch = HSL_PATTERN.exec(trimmed);
	if (hslMatch) {
		return hslToRgb(
			{
				h: Number.parseInt(hslMatch[1] ?? '0', 10),
				s: Number.parseInt(hslMatch[2] ?? '0', 10),
				l: Number.parseInt(hslMatch[3] ?? '0', 10)
			},
			hslMatch[4] ? Number.parseFloat(hslMatch[4]) : 1
		);
	}

	const hsbMatch = HSB_PATTERN.exec(trimmed);
	if (hsbMatch) {
		return hsvToRgb({
			h: Number.parseInt(hsbMatch[1] ?? '0', 10),
			s: Number.parseInt(hsbMatch[2] ?? '0', 10),
			v: Number.parseInt(hsbMatch[3] ?? '0', 10),
			a: hsbMatch[4] ? Number.parseFloat(hsbMatch[4]) : 1
		});
	}

	return null;
}

/** `first` for the head, `last` for the tail, `isolated` for a lone field, `middle` between. */
function positionAt(index: number, length: number): ColorPickerInputField['position'] {
	if (length === 1) return 'isolated';
	if (index === 0) return 'first';
	if (index === length - 1) return 'last';
	return 'middle';
}

/**
 * The channel model behind `<ColorPicker.Input>`. Replaces upstream's four near-identical input
 * components (`HexInput`/`RgbInput`/`HslInput`/`HsbInput`) with data, producing the same DOM, the
 * same `aria-label`s and the same validation bounds.
 */
export function getInputFields(input: ColorPickerInputFieldsInput): ColorPickerInputField[] {
	const { format, rgb, hsv, withoutAlpha } = input;

	const alphaPercent = `${Math.round(rgb.a * 100)}`;

	const fields: Omit<ColorPickerInputField, 'position'>[] = [];

	switch (format) {
		case 'rgb':
			fields.push(
				numeric('r', 'Red color component (0-255)', `${Math.round(rgb.r)}`, 0, 255),
				numeric('g', 'Green color component (0-255)', `${Math.round(rgb.g)}`, 0, 255),
				numeric('b', 'Blue color component (0-255)', `${Math.round(rgb.b)}`, 0, 255)
			);
			break;
		case 'hsl': {
			const hsl = rgbToHsl(rgb);
			fields.push(
				numeric('h', 'Hue degree (0-360)', `${hsl.h}`, 0, 360),
				numeric('s', 'Saturation percentage (0-100)', `${hsl.s}`, 0, 100),
				numeric('l', 'Lightness percentage (0-100)', `${hsl.l}`, 0, 100)
			);
			break;
		}
		case 'hsb':
			fields.push(
				numeric('h', 'Hue degree (0-360)', `${hsv.h}`, 0, 360),
				numeric('s', 'Saturation percentage (0-100)', `${hsv.s}`, 0, 100),
				numeric('v', 'Brightness percentage (0-100)', `${hsv.v}`, 0, 100)
			);
			break;
		default:
			fields.push({
				channel: 'hex',
				label: 'Hex color value',
				value: rgbToHex(rgb),
				placeholder: '#000000',
				numeric: false
			});
	}

	if (!withoutAlpha) {
		fields.push(numeric('a', 'Alpha transparency percentage', alphaPercent, 0, 100, '100'));
	}

	return fields.map((field, index) => ({
		...field,
		position: positionAt(index, fields.length)
	}));
}

function numeric(
	channel: ColorPickerInputChannel,
	label: string,
	value: string,
	min: number,
	max: number,
	placeholder = '0'
): Omit<ColorPickerInputField, 'position'> {
	return { channel, label, value, placeholder, numeric: true, min, max };
}

/**
 * The area's `aria-valuetext` and the string behind the swatch's accessible name: the saturation and
 * brightness the 2D area actually controls, plus the resulting colour in the active notation.
 */
export function describeColor(rgb: RgbaColor, hsv: HsvaColor, format: ColorFormat): string {
	return `Saturation ${hsv.s}%, brightness ${hsv.v}%, ${colorToString(rgb, format)}`;
}

import type { Direction } from '$lib/components/ui/direction-provider/index.js';
import { getContext, hasContext, setContext } from 'svelte';

import {
	clampChannel,
	colorToString,
	describeColor,
	getInputFields,
	hexToRgb,
	hslToRgb,
	hsvToRgb,
	parseColorString,
	rgbToHex,
	rgbToHsl,
	rgbToHsv,
	type ColorFormat,
	type ColorPickerInputChannel,
	type ColorPickerInputField,
	type HsvaColor,
	type RgbaColor
} from './color.js';

/**
 * The browser-native screen colour sampler, Chromium-only.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/EyeDropper
 */
export type EyeDropperApi = {
	open: (options?: { signal?: AbortSignal }) => Promise<{ sRGBHex: string }>;
};

declare global {
	interface Window {
		EyeDropper?: {
			new (): EyeDropperApi;
		};
	}
}

/**
 * The reactive values `<ColorPicker.Root>` hands its state class. Everything reactive arrives as a
 * getter rather than a snapshot, so the class keeps tracking the props after construction.
 */
export type ColorPickerRootStateProps = {
	readonly getValue: () => string;
	readonly setValue: (value: string) => void;
	readonly getOpen: () => boolean;
	readonly setOpen: (open: boolean) => void;
	readonly getFormat: () => ColorFormat;
	readonly setFormat: (format: ColorFormat) => void;
	readonly getModal: () => boolean;
	readonly getDir: () => Direction;
	readonly getInline: () => boolean;
	readonly getDisabled: () => boolean;
	readonly getReadOnly: () => boolean;
	readonly getRequired: () => boolean;
	readonly getName: () => string | undefined;
};

/** Whether two colours are identical channel for channel, used to make the value sync idempotent. */
function sameRgb(a: RgbaColor, b: RgbaColor): boolean {
	return a.r === b.r && a.g === b.g && a.b === b.b && a.a === b.a;
}

/**
 * Whether a colour string states its own alpha. Only the functional notations can — upstream's hex
 * parser takes six digits and no alpha — so anything else keeps the alpha already on screen, exactly
 * like upstream's `hexToRgb(valueProp, currentState.color.a)`.
 */
function carriesAlpha(value: string): boolean {
	return /^(?:rgba?|hsla?|hsba?)\(\s*[\d.]+\s*,\s*[\d.]+%?\s*,\s*[\d.]+%?\s*,\s*[\d.]+\s*\)$/i.test(
		value.trim()
	);
}

/** Read a colour string, preserving `alpha` when the notation does not carry one of its own. */
function readColor(value: string, alpha: number): RgbaColor {
	const parsed = parseColorString(value);
	if (!parsed) return hexToRgb(value, alpha);
	return carriesAlpha(value) ? parsed : { ...parsed, a: alpha };
}

/**
 * One instance per `<ColorPicker.Root>`, published on a `Symbol` context key and read by all ten
 * parts.
 *
 * Replaces upstream's hand-rolled `useSyncExternalStore` pub/sub — `listenersRef` + `stateRef` +
 * `subscribe`/`getState`/`notify` (`color-picker.tsx:414-593`) — which exists only so that a deep
 * part can subscribe to one slice without re-rendering the tree. Runes give that for free: a part
 * reading `root.hue` re-runs only when the hue moves (research R-01).
 *
 * Both RGBA *and* HSVA are stored, never derived from one another: `rgbToHsv` rounds to whole
 * percents, so deriving RGBA would drift the hex on every keystroke, and deriving HSVA would collapse
 * the hue to `0` the moment the area reaches the greyscale axis (research R-02).
 */
export class ColorPickerRootState {
	// $derived is lazy at runtime, but svelte-check's static analysis cannot see that and would flag
	// the field as read before its constructor assignment.
	#props!: ColorPickerRootStateProps;

	#rgb: RgbaColor = $state({ r: 0, g: 0, b: 0, a: 1 });
	#hsv: HsvaColor = $state({ h: 0, s: 0, v: 0, a: 1 });

	/**
	 * The last string this picker emitted. An incoming controlled `value` equal to it is the echo of
	 * our own write coming back through the binding, and re-parsing it would round an `hsl()`/`hsb()`
	 * string back into a slightly different colour on every interaction.
	 */
	#lastEmitted: string;

	readonly format: ColorFormat = $derived(this.#props.getFormat());
	readonly open: boolean = $derived(this.#props.getOpen());

	/**
	 * Whether the open popover traps focus and locks scrolling. bits-ui has no `modal` prop on
	 * `Popover.Root` — its equivalents live on the content — so `<ColorPicker.Content>` reads this and
	 * forwards it as `trapFocus`/`preventScroll`, which is exactly how Radix's own `modal` is wired.
	 */
	readonly modal: boolean = $derived(this.#props.getModal());

	readonly dir: Direction = $derived(this.#props.getDir());
	readonly inline: boolean = $derived(this.#props.getInline());
	readonly disabled: boolean = $derived(this.#props.getDisabled());
	readonly readOnly: boolean = $derived(this.#props.getReadOnly());
	readonly required: boolean = $derived(this.#props.getRequired());
	readonly name: string | undefined = $derived(this.#props.getName());

	/**
	 * Whether the picker has no colour at all — the caller handed it an empty `value`. This is the
	 * reachable form of upstream's `!color` branch, which decides between the swatch's
	 * `"Current color: …"` and `"No color selected"` accessible names.
	 */
	readonly isEmpty: boolean = $derived(this.#props.getValue().trim() === '');

	/** The authoritative colour. */
	get rgb(): RgbaColor {
		return this.#rgb;
	}

	/** The authoritative hue/saturation/brightness view of the same colour. */
	get hsv(): HsvaColor {
		return this.#hsv;
	}

	readonly hue: number = $derived(this.#hsv.h);
	readonly saturation: number = $derived(this.#hsv.s);
	readonly brightness: number = $derived(this.#hsv.v);
	readonly alpha: number = $derived(this.#rgb.a);
	readonly alphaPercent: number = $derived(Math.round(this.#rgb.a * 100));

	/** `#rrggbb` — what the hidden form input submits, whatever the display format (FR-014). */
	readonly hex: string = $derived(rgbToHex(this.#rgb));

	/** The colour in the active notation — what `onValueChange` emits. */
	readonly formatted: string = $derived(colorToString(this.#rgb, this.format));

	/** The area's `aria-valuetext`. */
	readonly valueText: string = $derived(describeColor(this.#rgb, this.#hsv, this.format));

	/** The field set of the active format, alpha included. See {@link getFields}. */
	readonly inputFields: ColorPickerInputField[] = $derived(this.getFields(false));

	constructor(props: ColorPickerRootStateProps) {
		this.#props = props;

		const seed = props.getValue();
		const rgb = parseColorString(seed) ?? hexToRgb(seed);
		this.#rgb = rgb;
		this.#hsv = { ...rgbToHsv(rgb), a: rgb.a };
		this.#lastEmitted = seed;
	}

	/**
	 * The field set of the active format, optionally without its alpha field. Reactive: it reads
	 * `format`, `rgb` and `hsv`, so a caller wrapping it in `$derived` re-runs on every colour change.
	 */
	getFields(withoutAlpha: boolean): ColorPickerInputField[] {
		return getInputFields({
			format: this.format,
			rgb: this.#rgb,
			hsv: this.#hsv,
			withoutAlpha
		});
	}

	/** Whether a colour mutation is allowed at all right now (FR-015). */
	get #mutable(): boolean {
		return !this.disabled && !this.readOnly;
	}

	#emit(): void {
		const next = colorToString(this.#rgb, this.format);
		this.#lastEmitted = next;
		this.#props.setValue(next);
	}

	/** Write the colour from RGBA, recomputing the HSVA view and emitting `onValueChange`. */
	setFromRgb(rgb: RgbaColor): void {
		if (!this.#mutable || sameRgb(rgb, this.#rgb)) return;
		this.#rgb = rgb;
		this.#hsv = { ...rgbToHsv(rgb), a: rgb.a };
		this.#emit();
	}

	/** Write the colour from HSVA, recomputing the RGBA view and emitting `onValueChange`. */
	setFromHsv(hsv: HsvaColor): void {
		if (!this.#mutable) return;
		const rgb = hsvToRgb(hsv);
		if (
			hsv.h === this.#hsv.h &&
			hsv.s === this.#hsv.s &&
			hsv.v === this.#hsv.v &&
			hsv.a === this.#hsv.a
		) {
			return;
		}
		this.#hsv = hsv;
		this.#rgb = rgb;
		this.#emit();
	}

	/** The hue slider's only mutator. */
	setHue(hue: number): void {
		this.setFromHsv({ ...this.#hsv, h: clampChannel(hue, 0, 360) });
	}

	/** The 2D area's only mutator. */
	setSaturationBrightness(saturation: number, brightness: number): void {
		this.setFromHsv({
			...this.#hsv,
			s: clampChannel(saturation, 0, 100),
			v: clampChannel(brightness, 0, 100)
		});
	}

	/** The alpha slider's only mutator. Alpha lives on both representations at once. */
	setAlpha(alpha: number): void {
		if (!this.#mutable) return;
		const next = Math.min(1, Math.max(0, alpha));
		if (next === this.#rgb.a) return;
		this.#rgb = { ...this.#rgb, a: next };
		this.#hsv = { ...this.#hsv, a: next };
		this.#emit();
	}

	/** Change the display format. Touches no colour state whatsoever (FR-003, research R-14). */
	setFormat(format: ColorFormat): void {
		if (format === this.format) return;
		this.#props.setFormat(format);
	}

	/** Open or close the popover. Ignored entirely when `inline`. */
	setOpen(open: boolean): void {
		if (open === this.open) return;
		this.#props.setOpen(open);
	}

	/**
	 * Commit one input field. Returns whether the raw text was accepted; an out-of-range or
	 * unparseable value is *rejected* rather than clamped, exactly like upstream's
	 * `if (!Number.isNaN(value) && value >= 0 && value <= max)` guards.
	 */
	commitField(channel: ColorPickerInputChannel, raw: string): boolean {
		if (!this.#mutable) return false;

		if (channel === 'hex') {
			const parsed = parseColorString(raw);
			if (!parsed) return false;
			this.setFromRgb({ ...parsed, a: this.#rgb.a });
			return true;
		}

		const value = Number.parseInt(raw, 10);
		if (Number.isNaN(value) || value < 0) return false;

		switch (channel) {
			case 'r':
			case 'g':
			case 'b': {
				if (value > 255) return false;
				this.setFromRgb({ ...this.#rgb, [channel]: value });
				return true;
			}
			case 'a': {
				if (value > 100) return false;
				this.setAlpha(value / 100);
				return true;
			}
			case 'h': {
				if (value > 360) return false;
				if (this.format === 'hsl') {
					this.setFromRgb(hslToRgb({ ...rgbToHsl(this.#rgb), h: value }, this.#rgb.a));
				} else {
					this.setFromHsv({ ...this.#hsv, h: value });
				}
				return true;
			}
			case 's': {
				if (value > 100) return false;
				if (this.format === 'hsl') {
					this.setFromRgb(hslToRgb({ ...rgbToHsl(this.#rgb), s: value }, this.#rgb.a));
				} else {
					this.setFromHsv({ ...this.#hsv, s: value });
				}
				return true;
			}
			case 'l': {
				if (value > 100) return false;
				this.setFromRgb(hslToRgb({ ...rgbToHsl(this.#rgb), l: value }, this.#rgb.a));
				return true;
			}
			case 'v': {
				if (value > 100) return false;
				this.setFromHsv({ ...this.#hsv, v: value });
				return true;
			}
		}
	}

	/**
	 * Adopt a colour handed in from outside — a controlled `value`, or a `bind:value` the parent
	 * rewrote. Deliberately *not* guarded on `disabled`/`readOnly`: those suppress user interaction,
	 * not a parent that owns the value.
	 */
	syncFromValue(value: string): void {
		if (value === this.#lastEmitted) return;
		this.#lastEmitted = value;

		const next = readColor(value, this.#rgb.a);
		if (sameRgb(next, this.#rgb)) return;

		this.#rgb = next;
		this.#hsv = { ...rgbToHsv(next), a: next.a };
	}
}

/** The reactive values `<ColorPicker.Area>` hands its own state. */
export type ColorPickerAreaStateProps = {
	readonly root: ColorPickerRootState;
	readonly getStep: () => number;
	readonly getShiftStep: () => number;
};

/**
 * The 2D saturation/brightness area's pointer geometry and keyboard model.
 *
 * The keyboard half has no upstream counterpart at all — upstream's `ColorPickerArea`
 * (`color-picker.tsx:777-911`) is a bare `<div>` with no role, no `tabindex` and no `keydown`
 * handler. The APG has no 2D-picker pattern, so the primary axis (saturation) is exposed through the
 * standard slider properties and the whole state through `aria-valuetext` (research R-04).
 */
export class ColorPickerAreaState {
	#props!: ColorPickerAreaStateProps;

	/** Whether a pointer drag is in flight, surfaced as `data-dragging`. */
	isDragging = $state(false);

	/** The fully saturated, fully bright form of the current hue — the area's base layer. */
	readonly backgroundColor: RgbaColor = $derived(
		hsvToRgb({ h: this.#props.root.hue, s: 100, v: 100, a: 1 })
	);

	readonly thumbLeft: string = $derived(`${this.#props.root.saturation}%`);
	readonly thumbTop: string = $derived(`${100 - this.#props.root.brightness}%`);

	constructor(props: ColorPickerAreaStateProps) {
		this.#props = props;
	}

	/** The picker this area reads its colour from and writes its saturation/brightness back to. */
	get root(): ColorPickerRootState {
		return this.#props.root;
	}

	/**
	 * Map a pointer position inside `rect` onto saturation/brightness. Out-of-rect positions clamp
	 * rather than erroring, and the x axis mirrors under `dir="rtl"` so the crosshair stays under the
	 * finger in a mirrored layout (research R-10). A zero-sized rect (jsdom, or a hidden panel) maps
	 * to the origin instead of dividing by zero.
	 */
	updateFromPointer(clientX: number, clientY: number, rect: DOMRect): void {
		const ratioX = rect.width > 0 ? (clientX - rect.left) / rect.width : 0;
		const ratioY = rect.height > 0 ? (clientY - rect.top) / rect.height : 0;

		const x = Math.max(0, Math.min(1, this.root.dir === 'rtl' ? 1 - ratioX : ratioX));
		const y = Math.max(0, Math.min(1, 1 - ratioY));

		this.root.setSaturationBrightness(Math.round(x * 100), Math.round(y * 100));
	}

	/**
	 * The R-04 key table. Returns whether the key was handled, which is what the part turns into a
	 * `preventDefault()`.
	 */
	onKeydown(event: KeyboardEvent): boolean {
		if (this.root.disabled || this.root.readOnly) return false;

		const step = event.shiftKey ? this.#props.getShiftStep() : this.#props.getStep();
		const shiftStep = this.#props.getShiftStep();
		const rtl = this.root.dir === 'rtl';

		let saturation = this.root.saturation;
		let brightness = this.root.brightness;

		switch (event.key) {
			case 'ArrowRight':
				saturation += rtl ? -step : step;
				break;
			case 'ArrowLeft':
				saturation += rtl ? step : -step;
				break;
			case 'ArrowUp':
				brightness += step;
				break;
			case 'ArrowDown':
				brightness -= step;
				break;
			case 'Home':
				saturation = 0;
				break;
			case 'End':
				saturation = 100;
				break;
			case 'PageUp':
				brightness += shiftStep;
				break;
			case 'PageDown':
				brightness -= shiftStep;
				break;
			default:
				return false;
		}

		this.root.setSaturationBrightness(saturation, brightness);
		return true;
	}
}

const COLOR_PICKER_CONTEXT_KEY = Symbol('color-picker');

/** Publish the root state. Called by `<ColorPicker.Root>` during its own initialisation. */
export function setColorPickerContext(state: ColorPickerRootState): ColorPickerRootState {
	return setContext(COLOR_PICKER_CONTEXT_KEY, state);
}

/**
 * Read the picker's reactive state, throwing when there is no `<ColorPicker.Root>` ancestor (FR-017).
 *
 * This is also the replacement for upstream's exported `useStore as useColorPicker` selector hook:
 * runes subscribe automatically, so a consumer reads the slice it needs straight off the returned
 * state (spec Assumptions, "`useColorPicker` selector hook").
 */
export function getColorPickerContext(consumerName: string): ColorPickerRootState {
	if (!hasContext(COLOR_PICKER_CONTEXT_KEY)) {
		throw new Error(`\`${consumerName}\` must be used within \`<ColorPicker.Root>\`.`);
	}
	return getContext<ColorPickerRootState>(COLOR_PICKER_CONTEXT_KEY);
}
